def execute():
    """
    Ensure all custom fields on Appointment Letter (candidate info, salary breakdown,
    logos and signature image uploads, locations, signatory details, and editable clauses)
    are created in the database and active on Frappe Cloud.
    """
    try:
        create_custom_fields({"Appointment Letter": appointment_letter_custom_fields}, ignore_validate=True)
        frappe.clear_cache(doctype="Appointment Letter")
        print("[setup_appointment_letter_custom_fields] Created custom fields for Appointment Letter.")
    except Exception as e:
        print(f"[setup_appointment_letter_custom_fields] Warning creating custom fields: {e}")
        frappe.log_error(f"setup_appointment_letter_custom_fields error: {e}", "setup_appointment_letter_custom_fields")

    # Reload print formats
    for pf in [
        "middle_east_travels_appointment_letter",
        "middle_east_holidays_appointment_letter",
        "employee_travels_appointment_letter",
        "employee_holidays_appointment_letter",
    ]:
        try:
            frappe.reload_doc("visa_crm", "print_format", pf)
        except Exception as e:
            print(f"Non-fatal reload print format {pf}: {e}")

    frappe.db.commit()
